/**
 * 2608 WS5 — the additive SAP content release 2608 delta for the affirm set.
 *
 * Loads prisma/seeds/value-stream/dataset-2608.json, generated by
 * `pnpm sap:2608:load-bdc` from the 14 BDC questionnaires in
 * sap-references/2608/ (sha256-pinned by the manifest). It runs AFTER the
 * 2602 base seed (./index.ts) and never edits a 2602 row's content:
 *
 *   - the NEW value stream / sub-process / questions from S4H_706 (Process
 *     Automation, new in the 2608 accelerator set) are upserted with
 *     releaseId = the 2608 SapContentRelease row;
 *   - the RE-LEVEL list sets `bdcLevel` on existing questions whose SAP
 *     verbatim text matched a row of a CHANGED 2608 workbook (S4H_420
 *     Sourcing & Procurement, S4H_1767 Retail). Nothing else on those rows
 *     changes.
 *
 * Idempotent: every write is an upsert or an update keyed by the natural id.
 */
import { readFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import type { PrismaClient } from "@prisma/client";

const __dirname = path.dirname(fileURLToPath(import.meta.url));

export type Dataset2608 = {
  meta: {
    sapRelease: string;
    generatedAt: string;
    sources: string[];
    counts: {
      newStreams: number;
      newSubProcesses: number;
      newQuestions: number;
      relevelled: number;
      relevelUnmatched: number;
    };
  };
  valueStreams: { id: string; name: string; isFoundation: boolean; displayOrder: number }[];
  subProcesses: { id: string; streamId: string; name: string; type: string; displayOrder: number }[];
  questions: {
    id: string;
    streamId: string;
    subProcessId: string;
    scopeItemRefs: string[];
    sapVerbatim: string;
    sapArea: string | null;
    sapTopic: string | null;
    sscuiRef: string | null;
    sourceQuestionnaire: string;
    placementBasis: string;
    status: "suggested";
    flag: string | null;
    statusNote: string;
    displayOrder: number;
    format: "decision" | "information";
    bdcLevel: string | null;
  }[];
  relevel: { id: string; bdcLevel: "L1" | "L2" | "L3"; sourceQuestionnaire: string; matchedRow: number }[];
};

export type ValueStream2608SeedResult = {
  release: string;
  streams: number;
  subProcesses: number;
  questions: number;
  relevelled: number;
  relevelSkipped: number;
};

const DATASET_PATH = path.join(__dirname, "dataset-2608.json");

export async function seedValueStream2608(prisma: PrismaClient): Promise<ValueStream2608SeedResult> {
  const data = JSON.parse(await readFile(DATASET_PATH, "utf-8")) as Dataset2608;

  const release = await prisma.sapContentRelease.findFirst({
    where: { release: "2608" },
    orderBy: { loadedAt: "desc" },
  });
  if (!release) {
    throw new Error("[seed:2608] no SapContentRelease row for 2608 — run `pnpm sap:2608:seed-release` first");
  }

  for (const s of data.valueStreams) {
    await prisma.affirmValueStream.upsert({
      where: { id: s.id },
      update: { name: s.name, isFoundation: s.isFoundation, displayOrder: s.displayOrder },
      create: s,
    });
  }
  for (const sp of data.subProcesses) {
    await prisma.affirmSubProcess.upsert({
      where: { id: sp.id },
      update: { streamId: sp.streamId, name: sp.name, type: sp.type, displayOrder: sp.displayOrder },
      create: sp,
    });
  }
  for (const q of data.questions) {
    const fields = {
      streamId: q.streamId,
      subProcessId: q.subProcessId,
      scopeItemRefs: q.scopeItemRefs,
      sapVerbatim: q.sapVerbatim,
      // Never invented: the plain-language wording is the consultant's curation step.
      plainLanguageSuggested: null,
      consultantWording: null,
      sapArea: q.sapArea,
      sapTopic: q.sapTopic,
      sscuiRef: q.sscuiRef,
      sourceQuestionnaire: q.sourceQuestionnaire,
      placementBasis: q.placementBasis,
      status: q.status,
      flag: q.flag,
      statusNote: q.statusNote,
      displayOrder: q.displayOrder,
      format: q.format,
      bdcLevel: q.bdcLevel,
      releaseId: release.id,
    };
    await prisma.affirmQuestion.upsert({ where: { id: q.id }, update: fields, create: { id: q.id, ...fields } });
  }

  // Re-level: only rows that exist; a missing 2602 row is skipped and counted, never created here.
  let relevelled = 0;
  let relevelSkipped = 0;
  for (const r of data.relevel) {
    const res = await prisma.affirmQuestion.updateMany({ where: { id: r.id }, data: { bdcLevel: r.bdcLevel } });
    if (res.count === 1) relevelled++;
    else relevelSkipped++;
  }

  const [streams, subProcesses, questions] = await Promise.all([
    prisma.affirmValueStream.count({ where: { id: { in: data.valueStreams.map((s) => s.id) } } }),
    prisma.affirmSubProcess.count({ where: { id: { in: data.subProcesses.map((s) => s.id) } } }),
    prisma.affirmQuestion.count({ where: { id: { in: data.questions.map((q) => q.id) }, releaseId: release.id } }),
  ]);
  const expected = data.meta.counts;
  if (
    streams !== expected.newStreams ||
    subProcesses !== expected.newSubProcesses ||
    questions !== expected.newQuestions
  ) {
    throw new Error(
      `[seed:2608] count drift: streams ${streams}/${expected.newStreams}, sub-processes ${subProcesses}/${expected.newSubProcesses}, questions ${questions}/${expected.newQuestions}`,
    );
  }
  return { release: release.release, streams, subProcesses, questions, relevelled, relevelSkipped };
}
